// Seam glue for glob (component src_leaves): calls the Rust implementation through the cxx bridge.
// Only included when CPP_RUST_IMPL_SRC_LEAVES is defined; the header is generated by cargo
// (rust/src_leaves/build.rs) into the cxxbridge directory that msvc/rust.targets adds to the include path.
#ifndef GLOB_RUST_HPP
#define GLOB_RUST_HPP

#include <cstring>
#include "src_leaves/src/lib.rs.h"

inline rust::Slice<const uint8_t> glob_rust_bytes(const char *s)
{
  return rust::Slice<const uint8_t>(reinterpret_cast<const uint8_t*>(s), std::strlen(s));
}

inline bool rust_glob_match(const char *pathname, const char *basename, const char *glob, bool icase, bool lead, bool path)
{
  return ugrep_rust::glob_match(glob_rust_bytes(pathname), glob_rust_bytes(basename), glob_rust_bytes(glob), icase, lead, path);
}

#endif
